  "inlineSchema": "generator client {\n  provider = \"prisma-client-js\"\n}\n\ndatasource db {\n  provider = \"sqlite\"\n  url      = env(\"DATABASE_URL\")\n}\n\nmodel User {\n  id           Int       @id @default(autoincrement())\n  email        String    @unique\n  passwordHash String\n  role         String    @default(\"admin\")\n  createdAt    DateTime  @default(now())\n  sessions     Session[]\n}\n\n// API session tokens for the admin panel (validated server-side).\nmodel Session {\n  id        Int      @id @default(autoincrement())\n  token     String   @unique\n  userId    Int\n  expiresAt DateTime\n  createdAt DateTime @default(now())\n  user      User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@index([userId])\n}\n\n// Content keys that the CMS can edit (hero, stats, services, tech, process,\n// cta, contact, login, footer, about, projects texts).\nmodel ContentKey {\n  id           Int                  @id @default(autoincrement())\n  key          String               @unique\n  section      String               @default(\"other\")\n  type         String               @default(\"text\") // text | textarea\n  order        Int                  @default(0)\n  updatedAt    DateTime             @updatedAt\n  translations ContentTranslation[]\n}\n\n// One row per (key, language). The five languages are es, en, pt, fr, de.\nmodel ContentTranslation {\n  id           Int        @id @default(autoincrement())\n  contentKeyId Int\n  lang         String\n  value        String     @default(\"\")\n  updatedAt    DateTime   @updatedAt\n  contentKey   ContentKey @relation(fields: [contentKeyId], references: [id], onDelete: Cascade)\n\n  @@unique([contentKeyId, lang])\n  @@index([lang])\n}\n\nmodel Project {\n  id           Int                  @id @default(autoincrement())\n  slug         String               @unique\n  industry     String\n  title        String\n  client       String?\n  year         String\n  color        String\n  icon         String\n  tagline      String\n  desc         String\n  tags         String               @default(\"[]\")\n  metrics      String               @default(\"[]\")\n  featured     Boolean              @default(false)\n  active       Boolean              @default(true)\n  order        Int                  @default(0)\n  translations ProjectTranslation[]\n\n  @@index([active])\n  @@index([featured])\n}\n\n// Per-language text for each project (title, tagline, desc). Missing\n// languages fall back to the canonical values stored on Project.\nmodel ProjectTranslation {\n  id        Int     @id @default(autoincrement())\n  projectId Int\n  lang      String\n  title     String  @default(\"\")\n  tagline   String  @default(\"\")\n  desc      String  @default(\"\")\n  project   Project @relation(fields: [projectId], references: [id], onDelete: Cascade)\n\n  @@unique([projectId, lang])\n}\n\n// Contact form submissions / sales leads. status flow:\n// new -> contacted -> in_progress -> won | lost\nmodel Lead {\n  id        Int      @id @default(autoincrement())\n  name      String\n  email     String\n  phone     String   @default(\"\")\n  company   String   @default(\"\")\n  service   String   @default(\"\")\n  budget    String   @default(\"\")\n  message   String   @default(\"\")\n  status    String   @default(\"new\") // new | contacted | in_progress | won | lost\n  notes     String   @default(\"\")\n  source    String   @default(\"contact\") // contact | manual\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([status])\n  @@index([createdAt])\n}\n\n// Services catalog (12 services). `featured` marks the 6 core services shown\n// on the home preview; the rest are \"specialized\". Text lives per-language in\n// ServiceTranslation (bullets/deliverables/process are JSON arrays).\nmodel Service {\n  id           Int                  @id @default(autoincrement())\n  slug         String               @unique // svc-web\n  kind         String               @unique // web\n  icon         String               @default(\"Layers\")\n  color        String               @default(\"#22D3EE\")\n  featured     Boolean              @default(false)\n  active       Boolean              @default(true)\n  order        Int                  @default(0)\n  translations ServiceTranslation[]\n\n  @@index([active])\n  @@index([featured])\n}\n\nmodel ServiceTranslation {\n  id           Int     @id @default(autoincrement())\n  serviceId    Int\n  lang         String\n  name         String  @default(\"\")\n  tagline      String  @default(\"\")\n  overview     String  @default(\"\")\n  bullets      String  @default(\"[]\") // JSON array\n  deliverables String  @default(\"[]\") // JSON array\n  process      String  @default(\"[]\") // JSON array\n  service      Service @relation(fields: [serviceId], references: [id], onDelete: Cascade)\n\n  @@unique([serviceId, lang])\n}\n\n// Technologies marquee (TechLoop). Icons are rendered client-side from the\n// bundled TECH_LOGOS map; the DB stores which are active/ordered/categorized.\nmodel Technology {\n  id       Int     @id @default(autoincrement())\n  name     String  @unique\n  color    String  @default(\"#22D3EE\")\n  category String  @default(\"Otros\") // Frontend | Backend | Cloud | Data | DevOps | Mobile | Diseño | IA\n  featured Boolean @default(true)\n  active   Boolean @default(true)\n  order    Int     @default(0)\n\n  @@index([active])\n}\n\n// Per-route, per-language SEO metadata (title, description, keywords, OG).\nmodel SeoEntry {\n  id            Int      @id @default(autoincrement())\n  route         String // home | servicios | svc-web | proyectos | nosotros | contacto | 404\n  lang          String\n  title         String   @default(\"\")\n  description   String   @default(\"\")\n  keywords      String   @default(\"\")\n  ogTitle       String   @default(\"\")\n  ogDescription String   @default(\"\")\n  ogImage       String   @default(\"\")\n  updatedAt     DateTime @updatedAt\n\n  @@unique([route, lang])\n}\n\n// Site-wide settings (section visibility, hero image, announcement, contact\n// details). `value` is a JSON object keyed by setting name.\nmodel SiteConfig {\n  id    Int    @id @default(autoincrement())\n  key   String @unique // sections | heroImage | announcement | contact\n  value String @default(\"{}\")\n}\n\n// Automatic backups taken before destructive operations (e.g. reset).\nmodel ContentSnapshot {\n  id        Int      @id @default(autoincrement())\n  kind      String   @default(\"backup\") // backup | reset-before | import-before\n  data      String // JSON: { content, projects, services, technologies }\n  createdAt DateTime @default(now())\n}\n",
